using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterCollectorLogicTests
{
    private readonly ITestOutputHelper logger;

    public GeneratedFormatterCollectorLogicTests(ITestOutputHelper logger)
    {
        this.logger = logger;
    }

    [Fact]
    public async Task Contractless_PublicMutableField_IsSerialized()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                public class FieldHolder
                {
                    public int MutableFieldXyz;

                    public int Prop { get; set; }
                }

                [GeneratedMessagePackFormatter]
                public partial class FieldHolderFormatter : IMessagePackFormatter<FieldHolder> { }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        (Compilation _, ImmutableArray<SyntaxTree> generated) = await this.RunGeneratorAsync(source);
        string formatterSource = FindUserFormatter(generated, "FieldHolderFormatter");
        Assert.Contains("MutableFieldXyz", formatterSource);
    }

    [Fact]
    public async Task Contractless_PublicReadonlyField_DoesNotBreakCompilation()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                public class ReadonlyHolder
                {
                    public readonly int ReadonlyFieldXyz;

                    public int Prop { get; set; }
                }

                [GeneratedMessagePackFormatter]
                public partial class ReadonlyHolderFormatter : IMessagePackFormatter<ReadonlyHolder> { }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        (Compilation output, ImmutableArray<SyntaxTree> _) = await this.RunGeneratorAsync(source);
        List<Diagnostic> errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        foreach (Diagnostic error in errors)
        {
            this.logger.WriteLine(error.ToString());
        }

        Assert.Empty(errors);
    }

    [Fact]
    public async Task AttributedType_IgnoreMember_IsHonoured()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [MessagePackObject]
                public class Tagged
                {
                    [Key(0)]
                    public int A { get; set; }

                    [IgnoreMember]
                    public int SecretXyz { get; set; }
                }

                [GeneratedMessagePackFormatter]
                public partial class UserTaggedFormatter : IMessagePackFormatter<Tagged> { }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        (Compilation _, ImmutableArray<SyntaxTree> generated) = await this.RunGeneratorAsync(source);
        string formatterSource = FindUserFormatter(generated, "UserTaggedFormatter");
        Assert.DoesNotContain("SecretXyz", formatterSource);
    }

    [Fact]
    public async Task ExplicitCallbackReceiver_DoesNotBreakCompilation()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                public class Cb : IMessagePackSerializationCallbackReceiver
                {
                    public int X { get; set; }

                    void IMessagePackSerializationCallbackReceiver.OnBeforeSerialize() { }

                    void IMessagePackSerializationCallbackReceiver.OnAfterDeserialize() { }
                }

                [GeneratedMessagePackFormatter]
                public partial class CbFormatter : IMessagePackFormatter<Cb> { }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        (Compilation output, ImmutableArray<SyntaxTree> _) = await this.RunGeneratorAsync(source);
        List<Diagnostic> errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        foreach (Diagnostic error in errors)
        {
            this.logger.WriteLine(error.ToString());
        }

        Assert.Empty(errors);
    }

    private static string FindUserFormatter(ImmutableArray<SyntaxTree> trees, string name)
    {
        SyntaxTree? tree = trees.FirstOrDefault(t => t.ToString().Contains("partial class " + name, StringComparison.Ordinal));
        Assert.NotNull(tree);
        return tree!.ToString();
    }

    private async Task<(Compilation Output, ImmutableArray<SyntaxTree> Generated)> RunGeneratorAsync(string source)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = framework.Concat<MetadataReference>(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();

        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, nullableContextOptions: NullableContextOptions.Enable));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new ISourceGenerator[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);

        foreach (Diagnostic diagnostic in generatorDiagnostics)
        {
            this.logger.WriteLine(diagnostic.ToString());
        }

        GeneratorDriverRunResult run = driver.GetRunResult();
        foreach (SyntaxTree tree in run.GeneratedTrees)
        {
            this.logger.WriteLine("// " + tree.FilePath);
            this.logger.WriteLine(tree.ToString());
        }

        return (output, run.GeneratedTrees);
    }
}
